test("niepoprawny slug nie wykonuje HTTP",async()=>{const request=vi.fn(),source=createArticleSource(request,"https://spring.example");expect(await source.article("../secret")).toBeNull();expect(request).not.toHaveBeenCalled();});
test("lista ma jawne pola, unikalne slugi i poprawne tytuły",()=>{expect(parseSummaries([{slug:"a",title:"A",secret:"x"}])).toEqual([{slug:"a",title:"A"}]);expect(()=>parseSummaries([{slug:"a",title:"A"},{slug:"a",title:"B"}])).toThrow("Powtórzony");expect(()=>parseSummaries([{slug:"a",title:" "}])).toThrow();expect(apiOrigin("http://localhost:8080")).toBe("http://localhost:8080");for(const origin of ["file:///x","https://u:p@spring.example","https://spring.example/path"])expect(()=>apiOrigin(origin)).toThrow();});
