test("error pokazuje komunikat bez szczegółów wyjątku i wywołuje reset",()=>{const reset=vi.fn();render(<ErrorView error={Error("TAJNY BŁĄD DB")} reset={reset}/>);expect(screen.getByRole("alert")).not.toHaveTextContent("TAJNY");fireEvent.click(screen.getByRole("button",{name:"Spróbuj ponownie"}));expect(reset).toHaveBeenCalledTimes(1);});

